# R48: a course (pages/course, the course editor): its page for a learner, the same page in an editor's Edit mode
# (title and summary in place, Properties: Shelf, Level, Length; About; Lessons dragged, removed, "Or add one back", Add
# lesson), its Settings page and Publish. Labels from learn.ts (course, own, edit.course, settings). Exec'd by r41.py.
CRS = {'t': 'Intro to Music Reading', 's': 'Read notes on both staves at sight, one clef at a time, then together.',
       'about': 'Eight short lessons, each with a song to read at the end. Read a little every day: reading grows by repetition more than by length.',
       'lessons': [['The staff and the treble clef', 'learned'], ['Notes on the lines', 'learned'], ['Notes in the spaces', 'learned'], ['The bass clef', 'next'], ['Ledger lines', ''], ['The grand staff', ''], ['Reading both hands', ''], ['Sight-reading a little every day', 'unpub']],
       'songs': [['Ode to Joy', 'Beethoven · Beginner'], ['Twinkle, Twinkle', 'Traditional · Beginner'], ['Amazing Grace', 'Traditional · Beginner']]}
COURSE_JS = js('const CR = ' + json.dumps(CRS, ensure_ascii=False) + ';\n' + r'''
    const editing = !!st.editing, sheet = st.sheet ?? null, gone = st.gone ?? {}, weeks = st.weeks ?? 4, shelf = st.shelf ?? 'Beginner courses', level = st.level ?? 'Beginner';
    const lessons = CR.lessons.filter(([t]) => !gone[t]).map(([t, k], i) => ({ t, n: 'Lesson ' + (i + 1), learned: k === 'learned', next: k === 'next', unpub: k === 'unpub', todo: k !== 'learned' && k !== 'next',
      num: String(i + 1), tileBg: k === 'learned' ? '#DCE9D6' : '#FEFDFB', ring: k === 'next' ? '0 0 0 2.5px #EDC684' : (k === 'learned' ? 'none' : '0 0 0 1px #DAD1C8'),
      remove: (e) => { e && e.preventDefault && e.preventDefault(); set({ gone: { ...gone, [t]: true }, toast: 'Removed: ' + t }); } }));
    const removed = CR.lessons.filter(([t]) => gone[t]).map(([t]) => ({ t, back: () => { const g = { ...gone }; delete g[t]; set({ gone: g }); } }));
    return { ...common(st, set), editing, reading: !editing, edit: () => set({ editing: true }), done: () => set({ editing: false, sheet: null }), status: 'Saved · not published',
      t: CR.t, s: CR.s, about: CR.about, lessons, songs: CR.songs.map(([t, d]) => ({ t, d })), removed, hasRemoved: removed.length > 0,
      shelves: chipsOf(['Beginner courses', 'Intermediate courses', 'Technique and exercises', 'Chords and improvisation', 'Method books'], shelf, (x) => set({ shelf: x })),
      levels: chipsOf(['Beginner', 'Intermediate', 'Advanced', 'Professional'], level, (x) => set({ level: x })), shelfV: shelf, levelV: level,
      weeksL: weeks + ' weeks', fewer: () => set({ weeks: Math.max(1, weeks - 1) }), more: () => set({ weeks: Math.min(52, weeks + 1) }),
      newOn: sheet === 'new', openNew: () => set({ sheet: 'new' }), create: () => set({ sheet: null, toast: 'Lesson added: New lesson' }),
      pmOn: sheet === 'pubmenu', openPm: () => set({ sheet: 'pubmenu' }), propOn: sheet === 'props', openProps: () => set({ sheet: 'props' }),
      page: st.page ?? null, onPage: !!st.page, isSet: st.page === 'settings', isPub: st.page === 'publish', openSettings: () => set({ page: 'settings', sheet: null }), openPub: () => set({ page: 'publish', sheet: null }), closePage: () => set({ page: null }),
      pageT: st.page === 'settings' ? 'Settings' : 'Publish', resetOn: sheet === 'reset', askReset: () => set({ sheet: 'reset' }), doReset: () => set({ sheet: null, toast: 'Progress reset' }), delOn: sheet === 'delete', askDel: () => set({ sheet: 'delete' }),
      publish: () => set({ page: null, toast: 'Published. Learners will receive it the next time they open the app.' }),
      toastOn: !!st.toast, toastT: st.toast || '', undo: () => set({ gone: {}, toast: null }), undoRemove: () => set({ gone: {}, toast: null }) };''')
COVER = (f'<div aria-hidden="true" style="height: 132px; border-radius: 18px; background: {HONEY}; position: relative; overflow: hidden">'
         f'<svg viewBox="0 0 400 132" preserveAspectRatio="xMidYMid slice" width="100%" height="100%"><g stroke="#C9A35C" stroke-width="1.6">' + ''.join(f'<line x1="0" x2="400" y1="{44 + i * 11}" y2="{44 + i * 11}"></line>' for i in range(5)) + '</g>'
         + ''.join(f'<ellipse cx="{70 + i * 46}" cy="{88 - (i % 4) * 5.5}" rx="7.5" ry="5.6" fill="#8A5A1C" transform="rotate(-20 {70 + i * 46} {88 - (i % 4) * 5.5})"></ellipse><line x1="{77 + i * 46}" x2="{77 + i * 46}" y1="{86 - (i % 4) * 5.5}" y2="{52 - (i % 4) * 5.5}" stroke="#8A5A1C" stroke-width="1.6"></line>' for i in range(7)) + '</svg></div>')
FACTS = f'<div style="display: flex; flex-wrap: wrap; gap: 6px">' + ''.join(f'<span style="height: 30px; padding: 0 12px; border-radius: 15px; background: {FILL}; font-size: 14px; font-weight: 600; display: flex; align-items: center">{x}</span>' for x in ['Beginner', '8 lessons', '3 songs', '4 weeks']) + '</div>'
PROPS = (f'<div aria-label="Properties" style="display: flex; flex-wrap: wrap; gap: 6px"><button type="button" onClick="{{{{openProps}}}}" style="height: 36px; padding: 0 12px; border: 0; border-radius: 18px; background: {FILL}; color: {INK}; font: inherit; font-size: 14px"><span style="color: {SOFT}">Shelf</span> {{{{shelfV}}}}</button>'
         f'<button type="button" onClick="{{{{openProps}}}}" style="height: 36px; padding: 0 12px; border: 0; border-radius: 18px; background: {FILL}; color: {INK}; font: inherit; font-size: 14px"><span style="color: {SOFT}">Level</span> {{{{levelV}}}}</button>'
         f'<span style="height: 36px; padding: 0 4px 0 12px; border-radius: 18px; background: {FILL}; font-size: 14px; display: flex; align-items: center; gap: 2px"><span style="color: {SOFT}">Length</span>&nbsp;{{{{weeksL}}}}<button type="button" aria-label="Fewer weeks" onClick="{{{{fewer}}}}" style="width: 36px; height: 36px; border: 0; background: transparent; font: inherit; font-size: 18px; color: {INK}">−</button><button type="button" aria-label="More weeks" onClick="{{{{more}}}}" style="width: 36px; height: 36px; border: 0; background: transparent; font: inherit; font-size: 18px; color: {INK}">+</button></span></div>')
GRIPS = '<span role="button" aria-label="Move: {{l.t}}" style="flex: none; width: 44px; height: 44px; color: #685E56; display: flex; align-items: center; justify-content: center; cursor: grab">' + GRIP + '</span>'
# canvas 164: a course's lessons are the line a level's are (one spine through the tiles, no card round them)
LROWS = (f'<div style="position: relative"><span aria-hidden="true" style="position: absolute; left: 31px; top: 32px; bottom: 32px; width: 2px; background: #B9CDB3"></span><sc-for list="{{{{lessons}}}}" as="l" hint-placeholder-count="8"><a href="Lesson.dc.html" style="position: relative; min-height: 64px; display: flex; align-items: center; gap: 12px; padding: 8px 8px 8px 12px; border-radius: 12px; color: {INK}; text-decoration: none">'
         f'<span style="flex: none; width: 40px; height: 40px; border-radius: 20px; background: {{{{l.tileBg}}}}; box-shadow: {{{{l.ring}}}}; color: #2F5A35; font-size: 14px; font-weight: 700; display: flex; align-items: center; justify-content: center"><sc-if value="{{{{l.learned}}}}" hint-placeholder-val="{{{{false}}}}">{CHECKI}</sc-if><sc-if value="{{{{l.todo}}}}" hint-placeholder-val="{{{{true}}}}"><span style="color: {SOFT}">{{{{l.num}}}}</span></sc-if><sc-if value="{{{{l.next}}}}" hint-placeholder-val="{{{{false}}}}"><span style="color: {INK}">{{{{l.num}}}}</span></sc-if></span>'
         f'<span style="flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px"><span style="font-size: 16px; font-weight: 600">{{{{l.t}}}}</span><span style="font-size: 14px; color: {SOFT}">{{{{l.n}}}}<sc-if value="{{{{l.unpub}}}}" hint-placeholder-val="{{{{false}}}}"><sc-if value="{{{{editing}}}}" hint-placeholder-val="{{{{false}}}}"> · <span style="color: #A8551F; font-weight: 600">Not published yet</span></sc-if></sc-if></span></span>'
         f'<sc-if value="{{{{reading}}}}" hint-placeholder-val="{{{{true}}}}"><sc-if value="{{{{l.next}}}}" hint-placeholder-val="{{{{false}}}}">{PILL("Next")}</sc-if></sc-if>'
         f'<sc-if value="{{{{reading}}}}" hint-placeholder-val="{{{{true}}}}"><span style="color: {SOFT}; display: flex; padding-right: 4px">{CHEV_R}</span></sc-if>'
         f'<sc-if value="{{{{editing}}}}" hint-placeholder-val="{{{{false}}}}"><button type="button" onClick="{{{{l.remove}}}}" style="flex: none; height: 44px; padding: 0 8px; border: 0; background: transparent; color: #B3261E; font: inherit; font-size: 15px; font-weight: 600">Remove</button>{GRIPS}</sc-if></a></sc-for></div>'
         f'<sc-if value="{{{{editing}}}}" hint-placeholder-val="{{{{false}}}}"><sc-if value="{{{{hasRemoved}}}}" hint-placeholder-val="{{{{false}}}}"><div style="display: flex; flex-wrap: wrap; align-items: center; gap: 6px"><span style="font-size: 14px; color: {SOFT}">Or add one back</span><sc-for list="{{{{removed}}}}" as="r" hint-placeholder-count="1"><button type="button" onClick="{{{{r.back}}}}" style="height: 36px; padding: 0 12px; border: 0; border-radius: 18px; background: {FILL}; color: {INK}; font: inherit; font-size: 14px; font-weight: 600">+ {{{{r.t}}}}</button></sc-for></div></sc-if>'
         f'<button type="button" onClick="{{{{openNew}}}}" style="height: 48px; border: 0; background: transparent; color: {LINK}; font: inherit; font-size: 16px; font-weight: 600; display: flex; align-items: center; gap: 8px; padding: 0 4px">{PLUS}Add lesson</button></sc-if>')
SONGROWS = (f'<div style="border-radius: 14px; background: {SHEET}; box-shadow: 0 0 0 1px {LINE}; overflow: hidden"><sc-for list="{{{{songs}}}}" as="g" hint-placeholder-count="3"><a href="Song.dc.html" style="min-height: 60px; display: flex; align-items: center; gap: 12px; padding: 8px 12px; box-shadow: inset 0 -1px 0 {FILL}; color: {INK}; text-decoration: none">'
            f'<span style="flex: none; width: 40px; height: 40px; border-radius: 10px; background: {SKY}; display: flex; align-items: center; justify-content: center">{NOTE}</span><span style="flex: 1; display: flex; flex-direction: column; gap: 2px"><span style="font-size: 16px; font-weight: 600">{{{{g.t}}}}</span><span style="font-size: 14px; color: {SOFT}">{{{{g.d}}}}</span></span><span style="color: {SOFT}; display: flex">{CHEV_R}</span></a></sc-for></div>')
def CBODY(lap):
    head = (f'<div style="display: flex; flex-direction: column; gap: 8px"><sc-if value="{{{{editing}}}}" hint-placeholder-val="{{{{false}}}}"><h1 contenteditable="true" style="margin: 0; font-family: {SERIF}; font-size: {36 if lap else 30}px; font-weight: 600; line-height: 1.15; outline: none">{{{{t}}}}</h1></sc-if>'
            f'<p contenteditable="{{{{editing}}}}" style="margin: 0; font-size: 17px; line-height: 1.5; color: {SOFT}; outline: none">{{{{s}}}}</p>'
            f'<sc-if value="{{{{reading}}}}" hint-placeholder-val="{{{{true}}}}">{FACTS}</sc-if><sc-if value="{{{{editing}}}}" hint-placeholder-val="{{{{false}}}}">{PROPS}</sc-if></div>')
    go = (f'<sc-if value="{{{{reading}}}}" hint-placeholder-val="{{{{true}}}}"><div style="display: flex; flex-direction: column; gap: 8px"><div style="display: flex; justify-content: space-between; font-size: 14px; color: {SOFT}"><span>3 of 8 learned</span><span>Next: The bass clef</span></div>{METER.replace("{{meter}}", "37%")}'
          f'<div style="display: flex; margin-top: 4px">{BTN("Continue", "", "Lesson.dc.html", "primary", 52)}</div></div></sc-if>')
    about = f'{H2("About")}<p contenteditable="{{{{editing}}}}" style="margin: 0 4px; font-size: 16px; line-height: 1.55; outline: none">{{{{about}}}}</p>'
    if lap:  # canvas 164: no narrow column in a wide screen; the course's card held in view, its lessons beside it
        return (f'<div style="width: 400px; flex: none; position: sticky; top: 0; display: flex; flex-direction: column; gap: 16px">{COVER}{head}{go}{about}</div>'
                f'<div style="flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 14px">{H2("Lessons")}{LROWS}{H2("Guided songs")}{SONGROWS}</div>')
    return COVER + head + go + about + H2('Lessons') + LROWS + H2('Guided songs') + SONGROWS
CBAR_R = IB('Settings', GEARI, 'openSettings') + f'<button type="button" onClick="{{{{edit}}}}" style="flex: none; height: 44px; padding: 0 16px; border: 0; border-radius: 22px; background: {FILL}; color: {INK}; font: inherit; font-size: 16px; font-weight: 700">Edit</button>'
CEDIT = (f'<header style="flex: none; display: flex; flex-direction: column; gap: 2px; padding: 0 16px 6px"><div style="min-height: 52px; display: flex; align-items: center; gap: 8px">{DONEBTN}<span style="flex: 1"></span>{IB("Publishing", DOTS, "openPm")}'
         f'<button type="button" onClick="{{{{openPub}}}}" style="flex: none; height: 44px; padding: 0 16px; border: 0; border-radius: 22px; background: {ACCENT}; color: {INK}; font: inherit; font-size: 16px; font-weight: 700">Publish…</button></div><div style="display: flex; justify-content: center">{DSTATUS}</div></header>')
CSET = (f'<span style="margin: -6px 4px 0; font-size: 15px; color: {SOFT}">Intro to Music Reading</span>'
        f'{CAPS("The course")}{GROUP(("link", "Shelf", "Beginner courses", "LearnCoursesLaptop.dc.html"), bg=SHEET)}{CAPS("Share")}{GROUP(("link", "Publish…", "Published", "openPub"), ("link", "Share link", "", "#"), bg=SHEET)}'
        f'{CAPS("Progress")}{GROUP(("action", "Reset progress", "doReset"), bg=SHEET)}{GROUP(("action", "Delete course", "askDel", "#B3261E"), bg=SHEET)}')
CPUB = (f'<div style="display: flex; align-items: center; justify-content: space-between; margin: 0 4px"><span style="font-family: {SERIF}; font-size: 26px">Intro to Music Reading</span>{PILL("Has changes", "#F8E1CF")}</div>'
        f'{CAPS("What changed")}<p style="margin: 0 4px; font-size: 15px; color: {SOFT}">Changes made since the last publication are saved and ready to publish.</p>'
        f'{GROUP(("link", "Learner preview", "8 lessons", "#"), ("link", "Link", "pianotrainer.app/courses/intro-reading", "#"), ("link", "View", "", "#"), ("link", "Versions", "3", "#"), bg=SHEET)}<div style="display: flex">{BTN("Publish new version", "publish", "", "primary", 50)}</div>{GROUP(("action", "Unpublish", "closePage", "#B3261E"), bg=SHEET)}')
CNEW = (f'{CAPS("Name")}<input placeholder="New lesson" aria-label="Name" style="height: 48px; box-sizing: border-box; border: 0; border-radius: 12px; background: {SHEET}; box-shadow: 0 0 0 1px {LINE}; padding: 0 12px; font: inherit; font-size: 16px; color: {INK}">'
        f'<div style="display: flex">{BTN("Create lesson", "create", "", "primary", 50)}</div>')
CPROPS = f'{CAPS("Shelf")}{KCHIPS("shelves")}{CAPS("Level")}{KCHIPS("levels")}'
CPM = GROUP(('link', 'Versions', '3', '#'), bg=SHEET) + GROUP(('action', 'Discard changes', 'closeSheet', '#B3261E'), bg=SHEET)
def CPAGE(lap):
    pad = 'padding: 24px 0 60px; align-items: center' if lap else 'padding: 8px 16px 40px'
    return (f'<sc-if value="{{{{onPage}}}}" hint-placeholder-val="{{{{false}}}}"><div style="position: absolute; inset: 0; z-index: 45; background: {PAGE}; display: flex; flex-direction: column">' + ('' if lap else '<div style="height: 54px; flex: none"></div>')
            + f'<header style="flex: none; min-height: 56px; display: flex; align-items: center; gap: 10px; padding: 0 16px{" 0 44px" if lap else ""}"><button type="button" aria-label="Back to the course" onClick="{{{{closePage}}}}" style="flex: none; width: 44px; height: 44px; border: 0; background: transparent; color: {INK}; display: flex; align-items: center; justify-content: center; margin-left: -10px">{CHEV_L}</button><h1 style="margin: 0; font-size: {30 if lap else 28}px; font-weight: 700; letter-spacing: -0.01em">{{{{pageT}}}}</h1></header>'
            f'<main class="nos" style="flex: 1; min-height: 0; overflow-y: auto; display: flex; flex-direction: column; {pad}"><div style="{"width: 704px; " if lap else ""}display: flex; flex-direction: column; gap: 14px"><sc-if value="{{{{isSet}}}}" hint-placeholder-val="{{{{true}}}}">{CSET}</sc-if><sc-if value="{{{{isPub}}}}" hint-placeholder-val="{{{{false}}}}">{CPUB}</sc-if></div></main></div></sc-if>')
CASKS = (ASK('delOn', 'Delete Intro to Music Reading?', 'Learners lose it the next time the app starts, with its unpublished changes and every saved version.', 'Delete course', 'closeSheet'))
cph = (f'<sc-if value="{{{{reading}}}}" hint-placeholder-val="{{{{true}}}}">{TITLEBAR("Intro to Music Reading", CBAR_R, "LearnCourses.dc.html", "Back to Courses", wrap=True)}</sc-if><sc-if value="{{{{editing}}}}" hint-placeholder-val="{{{{false}}}}">{CEDIT}</sc-if>'
       f'<main class="nos" style="flex: 1; min-height: 0; overflow-y: auto; padding: 4px 16px 60px; display: flex; flex-direction: column; gap: 16px">{CBODY(False)}</main>{TOASTE.replace("bottom: 112px", "bottom: 40px")}{CPAGE(False)}{CASKS}')
csh = BSHEET('newOn', 'New lesson', CNEW) + BSHEET('pmOn', 'Publishing', CPM) + BSHEET('propOn', 'Properties', CPROPS)
clm = (f'<sc-if value="{{{{reading}}}}" hint-placeholder-val="{{{{true}}}}">{LTITLEBAR("Intro to Music Reading", CBAR_R, "LearnCoursesLaptop.dc.html")}</sc-if><sc-if value="{{{{editing}}}}" hint-placeholder-val="{{{{false}}}}">{CEDIT.replace("padding: 0 16px 6px", "padding: 6px 40px 6px")}</sc-if>'
       f'<main class="nos" style="flex: 1; min-height: 0; overflow-y: auto; padding: 0 56px 60px; display: flex; align-items: flex-start"><div style="flex: 1; max-width: 1180px; display: flex; gap: 48px; align-items: flex-start">{CBODY(True)}</div></main>'
       f'{TOASTE.replace("bottom: 112px; z-index: 50", "bottom: 32px; left: auto; right: 40px; width: 420px; z-index: 50")}{CPAGE(True)}{CASKS}')
cpops = POPOVER('newOn', 'New lesson', CNEW, 'right: 480px; top: 520px', 380) + POPOVER('pmOn', 'Publishing', CPM, 'right: 160px; top: 60px', 320) + POPOVER('propOn', 'Properties', CPROPS, 'left: 460px; top: 300px', 460)
detail('Course', 'Intro to Music Reading', COURSE_JS, cph, clm, '', csh, cpops, 'Learn')
print('r48 course ok')
